@SpringBootTest @AutoConfigureMockMvc @Transactional
@TestPropertySource(properties=["spring.datasource.url=jdbc:h2:mem:apadrinhamentos;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","app.jwt-secret=0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"])
class ApadrinhamentoApiTests @Autowired constructor(val mvc:MockMvc,val db:JdbcTemplate,val json:ObjectMapper,val jwt:JwtEncoder) {
 @Autowired lateinit var generator:br.com.sysanimais.api.apadrinhamentos.service.ParcelasApadrinhamentoService
 @Autowired lateinit var sponsors:br.com.sysanimais.api.apadrinhamentos.repository.ApadrinhamentoRepository
 @jakarta.persistence.PersistenceContext lateinit var em:jakarta.persistence.EntityManager
 private val own="/api/me/sponsorships";private val internal="/api/ong/sponsorships"
 @BeforeEach fun fixtures(){
  db.update("INSERT INTO ong(id,nome,email) VALUES(1101,'ONG A','a@k81.invalid'),(1102,'ONG B','b@k81.invalid')")
  for((id,ong,role) in listOf(Triple(1101,1101,"administrador"),Triple(1102,1102,"administrador"),Triple(1103,null,"usuario"),Triple(1104,null,"usuario"),Triple(1105,1101,"voluntario"),Triple(1106,1101,"veterinario"),Triple(1107,null,"admin_plataforma")))db.update("INSERT INTO usuario(id,ong_id,nome,email,senha_hash,perfil,ativo) VALUES(?,?,?,?,?,?,true)",id,ong,"Pessoa $id","u$id@k81.invalid","x",role)
  for((id,ong) in listOf(1101 to 1101,1102 to 1102))db.update("INSERT INTO animal(id,ong_id,nome,especie,sexo,porte,data_entrada,situacao,situacao_atualizada_em,situacao_alterada_por,ativo,publicado,criado_em,atualizado_em,versao) VALUES(?,?,'Lua','CAO','FEMEA','MEDIO',CURRENT_DATE,'DISPONIVEL',CURRENT_TIMESTAMP,1101,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0)",id,ong)
 }
 private fun auth(id:Int):String{val now=Instant.now();return "Bearer "+jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().subject(id.toString()).issuedAt(now).expiresAt(now.plusSeconds(3600)).build())).tokenValue}
 private fun get(path:String,u:Int=1103)=mvc.get(path){header("Authorization",auth(u))}
 private fun post(path:String,b:String,u:Int=1103)=mvc.post(path){header("Authorization",auth(u));contentType=MediaType.APPLICATION_JSON;content=b}
 private fun patch(path:String,u:Int=1101,b:String?=null)=mvc.patch(path){header("Authorization",auth(u));if(b!=null){contentType=MediaType.APPLICATION_JSON;content=b}}
 private fun create(mode:String="MENSAL",value:String="36.15",u:Int=1103,animal:Int=1101):Long{val r=post("/api/sponsorships","""{"animalId":$animal,"modalidade":"$mode","valor":"$value"}""",u).andExpect{status{isCreated()};jsonPath("$.status"){value("ATIVO")};jsonPath("$.primeiraParcela.status"){value("PENDENTE")}}.andReturn();return json.readTree(r.response.contentAsString)["id"].asLong()}
 private fun parcela(id:Long)=db.queryForObject("SELECT id FROM parcela_apadrinhamento WHERE apadrinhamento_id=? ORDER BY numero LIMIT 1",Long::class.java,id)!!
 @Test fun `compromisso nao recebe dinheiro e duplicado ativo e recusado`(){val id=create();get("$own/$id").andExpect{status{isOk()};jsonPath("$.valor"){value("36.15")};jsonPath("$.padrinho"){doesNotExist()}};post("/api/sponsorships","""{"animalId":1101,"modalidade":"MENSAL","valor":"10.00"}""").andExpect{status{isConflict()}};create("UNICO");create(u=1104);assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM parcela_apadrinhamento",Int::class.java));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM movimentacao_financeira",Int::class.java))}
 @Test fun `decimal modalidade campos e perfil de criacao validados`(){for(v in listOf("0","-1","1.234","1e2","2,50","10000000000.00","01.20"))post("/api/sponsorships","""{"animalId":1101,"modalidade":"UNICO","valor":"$v"}""").andExpect{status{isBadRequest()}};for(b in listOf("""{"animalId":1101,"modalidade":"ANUAL","valor":"2.50"}""","""{"animalId":1101,"modalidade":"UNICO","valor":2.50}""","""{"animalId":1101,"modalidade":"UNICO","valor":"2.50","ongId":1102}"""))post("/api/sponsorships",b).andExpect{status{isBadRequest()}};for(u in listOf(1101,1105,1106,1107))post("/api/sponsorships","{}",u).andExpect{status{isForbidden()}};mvc.get(own).andExpect{status{isUnauthorized()}}}
 @Test fun `animal inelegivel e ong suspensa impedem criacao`(){for(state in listOf("EM_TRATAMENTO","ADOTADO","FALECIDO")){db.update("UPDATE animal SET situacao=? WHERE id=1101",state);em.clear();post("/api/sponsorships","""{"animalId":1101,"modalidade":"UNICO","valor":"10.00"}""").andExpect{status{isConflict()}}};db.update("UPDATE animal SET situacao='EM_PROCESSO_ADOCAO' WHERE id=1101");em.clear();create();db.update("UPDATE animal SET publicado=false WHERE id=1101");em.clear();post("/api/sponsorships","""{"animalId":1101,"modalidade":"UNICO","valor":"10.00"}""").andExpect{status{isConflict()}};db.update("UPDATE animal SET publicado=true WHERE id=1101");db.update("UPDATE ong SET situacao='SUSPENSA' WHERE id=1101");em.clear();post("/api/sponsorships","""{"animalId":1101,"modalidade":"UNICO","valor":"10.00"}""").andExpect{status{isConflict()}}}
 @Test fun `consultas isolam titular ong e perfis`(){val id=create();get(own,1104).andExpect{jsonPath("$.totalElements"){value(0)}};for(p in listOf("$own/$id","$own/$id/parcelas"))get(p,1104).andExpect{status{isNotFound()}};patch("$own/$id/cancelar",1104).andExpect{status{isNotFound()}};get("$internal/$id",1102).andExpect{status{isNotFound()}};patch("$internal/$id/encerrar",1102,"""{"justificativa":"Encerrar"}""").andExpect{status{isNotFound()}};get(internal,1105).andExpect{status{isOk()};jsonPath("$.content[0].padrinho.id"){value(1103)}};for(u in listOf(1103,1106,1107))get(internal,u).andExpect{status{isForbidden()}}}
 @Test fun `confirmacao manual unica integra financeiro existente e origem imutavel`(){val id=create();val part=parcela(id);get("/api/ong/finance/resumo",1101).andExpect{jsonPath("$.saldoRealizado"){value("0.00")}};patch("$internal/$id/parcelas/$part/confirmar",b="{}").andExpect{status{isOk()};jsonPath("$.status"){value("CONFIRMADA")};jsonPath("$.confirmadoPor.id"){value(1101)}};patch("$internal/$id/parcelas/$part/confirmar").andExpect{status{isConflict()}};get("/api/ong/finance/resumo",1101).andExpect{jsonPath("$.receitasRealizadas"){value("36.15")}};get("/api/ong/finance/movimentacoes",1101).andExpect{jsonPath("$.totalElements"){value(1)};jsonPath("$.content[0].origem.tipo"){value("APADRINHAMENTO")};jsonPath("$.content[0].origem.id"){value(part)}};val m=db.queryForObject("SELECT id FROM movimentacao_financeira WHERE parcela_apadrinhamento_id=?",Long::class.java,part)!!;patch("/api/ong/finance/movimentacoes/$m/cancelar").andExpect{status{isConflict()}};post("/api/ong/finance/movimentacoes","""{"tipo":"RECEITA","categoria":"APADRINHAMENTO","descricao":"Indevida","valor":"10.00"}""",1101).andExpect{status{isBadRequest()}}}
 @Test fun `confirmacoes exigem admin da ong e parcela correta`(){val id=create();val part=parcela(id);for(u in listOf(1103,1105,1106,1107))patch("$internal/$id/parcelas/$part/confirmar",u).andExpect{status{isForbidden()}};patch("$internal/$id/parcelas/$part/confirmar",1102).andExpect{status{isNotFound()}};patch("$internal/$id/parcelas/999999/confirmar").andExpect{status{isNotFound()}};patch("$internal/$id/parcelas/$part/confirmar",b="""{"valor":"100.00"}""").andExpect{status{isBadRequest()}}}
 @Test fun `geracao sob demanda materializa tres meses sem duplicar e filtra vencidas`(){val id=create();em.flush();em.clear();val start=LocalDate.now(ZoneOffset.UTC).minusMonths(2).withDayOfMonth(1);db.update("UPDATE apadrinhamento SET data_inicio=? WHERE id=?",start,id);db.update("UPDATE parcela_apadrinhamento SET vencimento=? WHERE apadrinhamento_id=?",start,id);get("$own/$id/parcelas").andExpect{status{isOk()};jsonPath("$.totalElements"){value(3)}};get("$own/$id/parcelas").andExpect{jsonPath("$.totalElements"){value(3)}};get("$internal/$id/parcelas?vencidas=true&size=1&page=1",1105).andExpect{status{isOk()};jsonPath("$.totalElements"){value(if(LocalDate.now(ZoneOffset.UTC).dayOfMonth==1)2 else 3)};jsonPath("$.number"){value(1)}};get("$internal?animalId=1101&modalidade=MENSAL&status=ATIVO",1105).andExpect{jsonPath("$.totalElements"){value(1)}};for(q in listOf("page=-1","size=101","page=2147483647&size=100","de=2026-02-30","de=2026-12-01&ate=2026-01-01"))get("$internal/$id/parcelas?$q",1105).andExpect{status{isBadRequest()}}}
 @Test fun `cancelamento mantem confirmadas pendentes e permite receber depois de encerrar`(){val id=create();val part=parcela(id);patch("$own/$id/cancelar",1103).andExpect{status{isOk()};jsonPath("$.status"){value("ENCERRADO")};jsonPath("$.motivoEncerramento"){value("CANCELAMENTO_USUARIO")}};patch("$own/$id/cancelar",1103).andExpect{status{isConflict()}};patch("$internal/$id/parcelas/$part/confirmar").andExpect{status{isOk()}};get("$own/$id/parcelas").andExpect{jsonPath("$.content[0].status"){value("CONFIRMADA")};jsonPath("$.content[0].confirmadoPor"){doesNotExist()}};create();get("$own?status=ENCERRADO").andExpect{jsonPath("$.totalElements"){value(1)}}}
 @Test fun `encerramento admin exige justificativa preserva parcelas e autoria`(){val id=create();patch("$internal/$id/encerrar",1105,"""{"justificativa":"Encerrar"}""").andExpect{status{isForbidden()}};patch("$internal/$id/encerrar",b="""{"justificativa":" "}""").andExpect{status{isBadRequest()}};patch("$internal/$id/encerrar",b="""{"justificativa":"Acordo registrado"}""").andExpect{status{isOk()};jsonPath("$.justificativaEncerramento"){value("Acordo registrado")};jsonPath("$.motivoEncerramento"){value("ENCERRAMENTO_ONG")}};assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM parcela_apadrinhamento WHERE apadrinhamento_id=?",Int::class.java,id))}
 @Test fun `adocao apenas encerra no ato de entrega`(){val id=create();val r=post("/api/adoption-requests","""{"animalId":1101}""",1104).andExpect{status{isCreated()}}.andReturn();val request=json.readTree(r.response.contentAsString)["id"].asLong();patch("/api/ong/adoption-requests/$request/aprovar").andExpect{status{isOk()}};get("$own/$id").andExpect{jsonPath("$.status"){value("ATIVO")}};post("/api/ong/adoption-requests/$request/confirmar-entrega","""{"entregaConfirmada":true}""",1101).andExpect{status{isOk()}};get("$own/$id").andExpect{jsonPath("$.status"){value("ENCERRADO")};jsonPath("$.motivoEncerramento"){value("ADOCAO_CONCLUIDA")}};assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM parcela_apadrinhamento WHERE apadrinhamento_id=?",Int::class.java,id))}
 @Test fun `falecimento encerra na mesma transicao`(){val id=create();patch("/api/ong/animais/1101/situacao",b="""{"situacao":"FALECIDO","versao":0}""").andExpect{status{isOk()}};get("$own/$id").andExpect{jsonPath("$.motivoEncerramento"){value("FALECIMENTO_ANIMAL")}}}

 @Test fun `unicidade fisica de parcelas e valores positivos`(){val id=create();val p=parcela(id);assertThrows(org.springframework.dao.DataIntegrityViolationException::class.java){db.update("INSERT INTO parcela_apadrinhamento(apadrinhamento_id,ong_id,numero,valor,vencimento,status,criado_em,atualizado_em,versao) SELECT apadrinhamento_id,ong_id,numero,valor,vencimento,status,criado_em,atualizado_em,versao FROM parcela_apadrinhamento WHERE id=?",p)};assertThrows(org.springframework.dao.DataIntegrityViolationException::class.java){db.update("UPDATE parcela_apadrinhamento SET valor=-1 WHERE id=?",p)}}
 @Test fun `aniversario de janeiro nao deriva e corte automatico exclui futuro`(){
  for((user,cutoff,expected) in listOf(Triple(1103,false,listOf("2026-01-31","2026-02-28","2026-03-31")),Triple(1104,true,listOf("2026-01-31","2026-02-28")))){
   val id=create(u=user);em.flush();em.clear()
   db.update("UPDATE apadrinhamento SET data_inicio='2026-01-31' WHERE id=?",id)
   db.update("UPDATE parcela_apadrinhamento SET vencimento='2026-01-31' WHERE apadrinhamento_id=?",id)
   val a=sponsors.findById(id).orElseThrow();generator.ensureDue(a,LocalDate.of(2026,3,1),cutoff)
   generator.ensureDue(a,LocalDate.of(2026,3,1),cutoff)
   assertEquals(expected,db.queryForList("SELECT CAST(vencimento AS VARCHAR) FROM parcela_apadrinhamento WHERE apadrinhamento_id=? ORDER BY numero",String::class.java,id))
  }
 }

}
